mapper.update:
UPDATE document_task SET status = 'RUNNING', lease_owner = #{leaseOwner}, lease_expires_at = #{leaseExpiresAt}, attempt_count = attempt_count + 1, started_at = #{now}, finished_at = NULL WHERE id IN
#{id}
AND status = 'PENDING'

UPDATE document_task
SET status = 'SUCCEEDED',
lease_owner = NULL,
lease_expires_at = NULL,
last_error = NULL,
finished_at = #{now}
WHERE id = #{id}
AND status = 'RUNNING'
AND lease_owner = #{leaseOwner}

UPDATE document_task
SET status = 'FAILED',
lease_owner = NULL,
lease_expires_at = NULL,
last_error = #{lastError},
finished_at = #{now}
WHERE id = #{id}
AND status = 'RUNNING'
AND lease_owner = #{leaseOwner}

UPDATE document_task
SET status = 'PENDING',
lease_owner = NULL,
lease_expires_at = NULL,
next_attempt_at = #{nextAttemptAt},
last_error = #{lastError}
WHERE id = #{id}
AND status = 'RUNNING'
AND lease_owner = #{leaseOwner}

